import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// A naive custom 2D convolution kernel supporting stride, padding, dilation, groups, bias.
// This implementation does direct convolution and may not be highly optimized, but demonstrates
// how to replace PyTorch's built-in Conv2d with a custom CUDA operator.
__global__ void custom_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    const int N,
    const int C_in,
    const int H_in,
    const int W_in,
    const int C_out,
    const int kernel_h,
    const int kernel_w,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dilation_h,
    const int dilation_w,
    const int out_h,
    const int out_w,
    const int groups,
    const bool has_bias)
{
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * C_out * out_h * out_w;
    if (tid >= total_threads) {
        return;
    }

    // Decompose the linear index tid into n, c_out, h_out, w_out
    int temp = tid;
    int n = temp / (C_out * out_h * out_w);
    temp = temp % (C_out * out_h * out_w);
    int co = temp / (out_h * out_w);
    temp = temp % (out_h * out_w);
    int ho = temp / out_w;
    int wo = temp % out_w;

    // Determine group info
    int c_out_per_group = C_out / groups;
    int grp_id = co / c_out_per_group; 
    int c_in_start = grp_id * (C_in / groups);
    int c_in_end   = c_in_start + (C_in / groups);

    float val = 0.0f;
    // The weight layout is (C_out, C_in/groups, kernel_h, kernel_w)
    // The input layout is (N, C_in, H_in, W_in)
    // The output layout is (N, C_out, out_h, out_w)

    for(int ci = c_in_start; ci < c_in_end; ci++){
        for(int kh = 0; kh < kernel_h; kh++){
            for(int kw = 0; kw < kernel_w; kw++){
                int in_h = ho * stride_h - pad_h + kh * dilation_h;
                int in_w = wo * stride_w - pad_w + kw * dilation_w;
                if(in_h >= 0 && in_h < H_in && in_w >= 0 && in_w < W_in){
                    int input_idx  = ((n * C_in + ci) * H_in + in_h) * W_in + in_w;
                    int weight_idx = (((co) * (C_in/groups) + (ci - c_in_start)) * kernel_h + kh) * kernel_w + kw;
                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }
    if(has_bias){
        val += bias[co];
    }

    int out_idx = ((n * C_out + co) * out_h + ho) * out_w + wo;
    output[out_idx] = val;
}

torch::Tensor custom_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    int groups,
    bool has_bias)
{
    // input:  [N, C_in, H_in, W_in]
    // weight: [C_out, C_in/groups, kernel_h, kernel_w]
    // bias:   [C_out] or empty if has_bias=False

    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_out = weight.size(0);
    int kernel_h = weight.size(2);
    int kernel_w = weight.size(3);

    // Calculate output height/width
    int out_h = (H_in + 2*pad_h - dilation_h*(kernel_h-1) - 1) / stride_h + 1;
    int out_w = (W_in + 2*pad_w - dilation_w*(kernel_w-1) - 1) / stride_w + 1;

    // Create output tensor
    auto out_options = input.options().dtype(input.dtype());
    auto output = torch::zeros({N, C_out, out_h, out_w}, out_options);

    // Launch kernel
    int total_threads = N * C_out * out_h * out_w;
    int block_size = 256;
    int grid_size = (total_threads + block_size - 1) / block_size;

    custom_conv2d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N,
        C_in,
        H_in,
        W_in,
        C_out,
        kernel_h,
        kernel_w,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dilation_h,
        dilation_w,
        out_h,
        out_w,
        groups,
        has_bias
    );
    return output;
}
