conv2d_header = """
torch::Tensor custom_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    int groups,
    bool has_bias
);
"""

# Compile and load the custom operator
custom_conv2d = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_header,
    cuda_sources=conv2d_source,
    functions=["custom_conv2d_cuda"],
    extra_cflags=["-O2"],
    extra_cuda_cflags=["-O2"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    This class replaces PyTorch's built-in Conv2d with a naive custom CUDA convolution kernel.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        # Manually create weight and bias as trainable Parameters
        # Weight shape is [out_channels, in_channels // groups, kernel_size[0], kernel_size[1]]
        self.weight = nn.Parameter(
            torch.randn(
                out_channels,
                in_channels // groups,
                kernel_size[0],
                kernel_size[1]
            )
        )
        if self.has_bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # We directly call the custom CUDA convolution
        return custom_conv2d.custom_conv2d_cuda(
            x,
            self.weight,
            self.bias if self.has_bias else torch.tensor([]).to(x.device),
            self.stride[0],
            self.stride[1],
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
            self.groups,
            self.has_bias
        )

